public class BooleanOptionHandler_parseArguments_TriageGen1Test {

    @Mock
    private com.google.javascript.jscomp.CommandLineRunner.Flags.CmdLineParser mockParser;
    @Mock
    private com.google.javascript.jscomp.CommandLineRunner.Flags.OptionDef mockOptionDef;
    @Mock
    private Setter<Boolean> mockSetter;
    @Mock
    private Parameters mockParams;

    private BooleanOptionHandler handler;

    // These constants are assumed based on the logic provided in the snippet
    // Since they aren't provided in the prompt, we assume standard boolean strings 
    // or that the test environment provides them via the class constants.
    // For the sake of the test, we assume TRUES contains "true" and FALSES contains "false".

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        handler = new BooleanOptionHandler(mockParser, mockOptionDef, mockSetter);
    }

    @Test
    public void testParseArguments_NullParam() throws Exception {
        when(mockParams.getParameter(0)).thenReturn(null);

        int result = handler.parseArguments(mockParams);

        assertEquals(0, result);
        verify(mockSetter).addValue(true);
    }

    @Test
    public void testParseArguments_TrueParam() throws Exception {
        // Assuming "true" is in TRUES
        when(mockParams.getParameter(0)).thenReturn("true");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(true);
    }

    @Test
    public void testParseArguments_TrueParamMixedCase() throws Exception {
        // Testing toLowerCase() logic
        when(mockParams.getParameter(0)).thenReturn("TrUe");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(true);
    }

    @Test
    public void testParseArguments_FalseParam() throws Exception {
        // Assuming "false" is in FALSES
        when(mockParams.getParameter(0)).thenReturn("false");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(false);
    }

    @Test
    public void testParseArguments_FalseParamMixedCase() throws Exception {
        when(mockParams.getParameter(0)).thenReturn("FALSE");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(false);
    }

    @Test
    public void testParseArguments_UnknownParam() throws Exception {
        // Testing the final else block
        when(mockParams.getParameter(0)).thenReturn("unknown");

        int result = handler.parseArguments(mockParams);

        assertEquals(0, result);
        verify(mockSetter).addValue(true);
    }
}
